<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';$role=$_SESSION['kode_role'];if(!in_array($role,['ADMIN','DEKANAT','REKTORAT'],true)){http_response_code(403);die('403 - Akses ditolak.');}$where=[];$params=[];$types='';if($role==='DEKANAT'){$where[]='f.id_fakultas=?';$params[]=(int)$_SESSION['id_fakultas'];$types='i';}$sql="SELECT f.nama_fakultas,ps.nama_program_studi,ps.jenjang,COUNT(m.id_mahasiswa) total,SUM(m.status_mahasiswa='Aktif') aktif,SUM(m.status_mahasiswa='Lulus') lulus,SUM(m.status_mahasiswa='Cuti') cuti FROM program_studi ps JOIN fakultas f ON ps.id_fakultas=f.id_fakultas LEFT JOIN mahasiswa m ON m.id_program_studi=ps.id_program_studi".(count($where)?' WHERE '.implode(' AND ',$where):'')." GROUP BY ps.id_program_studi ORDER BY f.nama_fakultas,ps.nama_program_studi";$st=mysqli_prepare($koneksi,$sql);if($params)mysqli_stmt_bind_param($st,$types,...$params);mysqli_stmt_execute($st);$result=mysqli_stmt_get_result($st);?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laporan Mahasiswa</title><link rel="stylesheet" href="style.css"><style>@media print{.topbar,.sidebar,.no-print{display:none!important}.main-content{margin:0;padding:20px}}</style></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading page-heading-flex"><div><span class="eyebrow">LAPORAN</span><h1>Rekap Mahasiswa</h1><p>Rekap jumlah mahasiswa per Program Studi.</p></div><button class="btn btn-primary no-print" onclick="window.print()">🖨 Cetak</button></div><div class="dashboard-panel"><div class="table-responsive"><table class="data-table"><thead><tr><th>No</th><th>Fakultas</th><th>Program Studi</th><th>Jenjang</th><th>Total</th><th>Aktif</th><th>Cuti</th><th>Lulus</th></tr></thead><tbody><?php $no=1;while($r=mysqli_fetch_assoc($result)):?><tr><td><?=$no++?></td><td><?=e($r['nama_fakultas'])?></td><td><?=e($r['nama_program_studi'])?></td><td><?=e($r['jenjang'])?></td><td><?=$r['total']?></td><td><?=$r['aktif']?></td><td><?=$r['cuti']?></td><td><?=$r['lulus']?></td></tr><?php endwhile;?></tbody></table></div></div></main><script src="script.js"></script></body></html>